mapper.select:
SELECT

FROM course_detail cd
LEFT JOIN course c ON cd.course_id = c.id
LEFT JOIN user u ON cd.uploader_user_id = u.id

    cd.status = 1
    AND cd.year BETWEEN #{minYear} AND #{maxYear}

        AND cd.courseType = #{courseType}


        AND cd.course_id = #{courseId}


        AND cd.year = #{year}



        AND (
            cd.title LIKE #{keywordLike}
            OR c.course_name LIKE #{keywordLike}
            OR cd.custom_subject LIKE #{keywordLike}
            OR COALESCE(NULLIF(u.teamname, ''), NULLIF(u.realname, ''), u.username, cd.author) LIKE #{keywordLike}
        )


ORDER BY cd.create_time DESC, cd.id DESC

SELECT COUNT(*)
FROM course_detail cd
WHERE cd.status = 1

    AND cd.id <> #{excludeCourseId}

  AND (
    TRIM(LEADING '/' FROM REPLACE(COALESCE(NULLIF(TRIM(cd.cover_path), ''), NULLIF(TRIM(cd.thumbnail_url), '')), CHAR(92), '/')) = #{relativePath}
    OR TRIM(LEADING '/' FROM REPLACE(COALESCE(NULLIF(TRIM(cd.original_file_path), ''), NULLIF(TRIM(cd.files), '')), CHAR(92), '/')) = #{relativePath}
    OR TRIM(LEADING '/' FROM REPLACE(NULLIF(TRIM(cd.preview_file_path), ''), CHAR(92), '/')) = #{relativePath}
  )
